mapper.update:
update cbdses_table_field
set is_show = #{isShow}
where table_code = #{tableCode}
  and field_code = #{fieldCode}

mapper.select:
SELECT ta.id tableId, ta.table_name tableName, ta.table_code tableCode, ta.is_loop isLoop, ta.primary_code primaryCode, ta.slave_type slaveType, ta.related_field relatedField, ta.main_table_code mainTableCode, fi.id fieldId, fi.field_name fieldName, fi.field_code fieldCode, fi.field_type fieldType, fi.data_type dataType, fi.is_show isShow FROM cbdses_table ta inner join cbdses_table_field fi on ta.id = fi.table_id
and ta.table_name = #{tableName}
and fi.field_name = #{fieldName} and ta.is_deleted = 0 and ta.is_effective = 1 and fi.is_deleted = 0 and fi.is_effective = 1

SELECT ta.id tableId, ta.table_name tableName, ta.table_code tableCode, ta.is_loop isLoop, ta.primary_code primaryCode, ta.slave_type slaveType, ta.related_field relatedField, ta.main_table_code mainTableCode, fi.id fieldId, fi.field_name fieldName, fi.field_code fieldCode, fi.field_type fieldType FROM cbdses_table ta inner join cbdses_table_field fi on ta.id = fi.table_id where ta.id in
#{el}
and fi.field_type = 1
